      SUBROUTINE WOECC     PRINTING OF MISALIGNMENT TABLESCC ----------------------------------------------------------------------      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8B.CIN'      INCLUDE 'ELM8C.CIN'      INCLUDE 'ELM8H.CIN'      INCLUDE 'ELM8J.CIN'      INCLUDE 'ELM8M.CIN'      INCLUDE 'ELM13C.CIN'      INCLUDE 'ELM15B.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'IOUNIT.CIN'C ---------------------------------------------------------------------      CHARACTER*1     BLANK      CHARACTER*18    ABOPX      CHARACTER*27    ABMEF, ABMEG      CHARACTER*19    ABMC      CHARACTER*27    ABDES      INTEGER         I2MOD, J, JJ, JL1, JL2, K, KA, KH      INTEGER         L1, L2, L1L2, N      REAL            CEO, LCM1, LCM2, OUTPUT(12), SIO, WORK      DATA BLANK      /' '/      DATA ABOPX      /'MAGNET AXIS COORDS'/      DATA ABMC       /'MAGNET CHORD COORDS'/      DATA ABMEF      /'MAGNET ENTRANCE FACE COORDS'/      DATA ABMEG      /'MAGNET EXIT FACE COORDS'/C      IF (.NOT. LCPR) THEN        WORK = LC/UFLOOR(1)        WRITE (NOUT,1004) WORK, XDIME(8) 1004   FORMAT (1H ,8X,F10.3,1X,A4)        LCPR = .TRUE.      ENDIFC      WRITE (NOUT,1010) 1010 FORMAT (1H0)      IF (TMK .EQ. 0) WRITE (NOUT,1005) 1005 FORMAT (' *PIVOT AT MAGNET ENTRANCE')      IF (TMK .EQ. 1) WRITE (NOUT,1006) 1006 FORMAT (' *PIVOT AT MAGNET CENTER')      IF (TMK .EQ. 2) WRITE (NOUT,1007) 1007 FORMAT (' *PIVOT AT MAGNET EXIT')      IF (FEO) WRITE (NOUT,1009) 1009 FORMAT (' *FOCUSING EFFECT ONLY')C      DO 2 J = 1, 6      I2MOD = 2 - MOD(J,2)    2 OUTPUT(J) = VM(J)/UMIS(I2MOD)      WRITE (NOUT,1000) 1000 FORMAT (48H *MISALIGNMENT EFFECT TABLE FOR MISALIGNMENTS OF )      WRITE (NOUT,1001) OUTPUT(1), XMIS(1), OUTPUT(2), XMIS(2),     1                  OUTPUT(3), XMIS(1), OUTPUT(4), XMIS(2),     2                  OUTPUT(5), XMIS(1), OUTPUT(6), XMIS(2) 1001 FORMAT (1H ,6(1X,F10.3,1X,A4,6X))C      DO 100 N = 1, NMMAX      IF (.NOT. LNMT(N)) GO TO 100      LCM1 = LMIS(1,N)/UFLOOR(1)      LCM2 = LMIS(2,N)/UFLOOR(1)      CHORD = CHORDT(N)      ABDES = BLANK      IF (STRATE(N)) THEN        ABDES(1:18) = ABOPX      ELSE        IF (CHORD) THEN          ABDES(1:19) = ABMC        ELSE IF (TMK .EQ. 0 .OR. TMK .EQ. 1) THEN          ABDES(1:27) = ABMEF        ELSE IF (TMK .EQ. 2) THEN          ABDES(1:27) = ABMEG        ENDIF      ENDIFC      WRITE (NOUT,1002) LABM(N), LCM1, XDIME(8), LCM2, XDIME(8),     1                  ABDES 1002 FORMAT (17H0*MISALIGNMENT OF ,1X,A4,3H* (,F10.3,1X,A4,3H TO,     1        F10.3,1X,A4,')',2X,A27)C      DO 90 J = 1, 6      JJ = 7*J - 6      DO 30 K = 1, 6      CEO = COM(J,K,N)      IF (.NOT. R2PM(N)) THEN        SIO = SQRT(SIM(JJ,K,N))      ELSE        SIO = 0.0        DO 20 L1 = 1, 6        JL1 = J + 6*L1 - 6        DO 20 L2 = 1, 6        JL2 = J + 6*L2 - 6        L1L2 = 6*L2 + L1 - 6        SIO = SIO + RC2M(JL1,K,N)*SIM(L1L2,K,N)*RC2M(JL2,K,N)   20   CONTINUE        SIO = SQRT(SIO)      ENDIF      KA = 2*K - 1      KH = 2*K      OUTPUT(KA) = CEO/UBEAM(J)      OUTPUT(KH) = SIO/UBEAM(J)   30 CONTINUE      WRITE (NOUT,1003) (OUTPUT(2*K-1), OUTPUT(2*K), XDIME(J), K = 1, 6) 1003 FORMAT (1H ,6(2F8.3,1X,A4,1X))   50 CONTINUE   90 CONTINUE  100 CONTINUEC      RETURN      END